{
  "command": "git show 78a7da3 --stat && git show 78a7da3 | head -300",
  "description": "Inspect the birth-cloud dust commit"
}

{
  "command": "grep -rn \"birth_cloud_dust\" --include=*.py --include=*.json --include=*.ipynb --include=*.md --include=*.html . | grep -v \"^./data/\" | grep -iv \"results\\|runs/\" | head -40",
  "description": "Find other birth_cloud_dust defaults"
}

{
  "command": "grep -rn \"birth_cloud_dust\" . --include='*.py' --include='*.json' --include='*.ipynb' --include='*.md' --include='*.html' 2>/dev/null | grep -v '^./data/' | cut -c1-220 | head -40",
  "description": "Find other birth_cloud_dust references"
}

{
  "command": "sed -i '' 's/\"    \\\\\"birth_cloud_dust\\\\\": False,  # True: power-law/\"    \\\\\"birth_cloud_dust\\\\\": True,  # True: power-law/' notebooks/ceridwen_integrated_photometry_spectra.ipynb && git diff && python3 -m pytest -q tests/test_dust_bump.py tests/test_ceridwen_dr2_production.py 2>&1 | tail -3",
  "description": "Flip default back to True and run related tests"
}

{
  "command": "git -C ceridwen status --short | head; python3 -m pytest -q tests/test_dust_bump.py 2>&1 | grep -E \"Error|error\" | head -5",
  "description": "Check submodule dirt and test collection error"
}

{
  "command": "ls -d .venv venv 2>/dev/null; for p in .venv/bin/python venv/bin/python $(which -a python python3 2>/dev/null); do $p -c \"import jax\" 2>/dev/null && echo \"OK $p\"; done",
  "description": "Locate a Python interpreter with jax"
}

{
  "command": ".venv/bin/python -m pytest -q tests/test_dust_bump.py tests/test_ceridwen_dr2_production.py 2>&1 | tail -3",
  "description": "Run dust and production tests"
}

{
  "command": ".venv/bin/python -m pytest -q tests/test_dust_bump.py 2>&1 | grep -E \"^E \" | head -5; .venv/bin/python -m pytest -q tests/test_ceridwen_dr2_production.py 2>&1 | tail -2",
  "description": "Show collection error and run production tests"
}

{
  "command": ".venv/bin/python -m pytest -q tests/test_ceridwen_dr2_production.py 2>&1 | grep FAILED | sed 's/ - .*//' > $TMPDIR/after.txt; git stash -q -- notebooks/ceridwen_integrated_photometry_spectra.ipynb && .venv/bin/python -m pytest -q tests/test_ceridwen_dr2_production.py 2>&1 | grep FAILED | sed 's/ - .*//' > $TMPDIR/before.txt; git stash pop -q; diff $TMPDIR/before.txt $TMPDIR/after.txt && echo SAME; wc -l < $TMPDIR/before.txt; .venv/bin/python -m pytest -q tests/test_ceridwen_dr2_production.py 2>&1 | grep -E \"^E \" | sort | uniq -c | head -5",
  "description": "Compare test failures with and without the change"
}

{
  "command": "git add notebooks/ceridwen_integrated_photometry_spectra.ipynb && git commit -q -m \"Birth-cloud dust on by default\n\nCo-Authored-By: Claude Opus 5.5 <noreply@anthropic.com>\" && git log --oneline -1 && git push 2>&1 | tail -3",
  "description": "Commit the default change and push"
}
